describe('handle', () => {
  it('creates a Notion page with correct field mapping on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.notion.com/v1/pages' && req.method === 'POST'
        ? jsonResponse(TARGET_ENDPOINTS[0].response, 200)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: PipedriveDealPayload = {
      title: 'Test Deal',
      value: 5000,
      owner: 'John Smith',
      close_date: '2024-07-15',
    }

    const config: ConnectorConfig = {
      notionApiKey: 'secret-key',
      notionDatabaseId: 'db-123',
      fetch,
    }

    const result = await handle(payload, config)

    expect(result.pageId).toBe('page-id-generated-by-notion')
    expect(calls).toHaveLength(1)

    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://api.notion.com/v1/pages')
    expect(call.headers.get('authorization')).toBe('Bearer secret-key')
    expect(call.headers.get('notion-version')).toBe('2022-06-28')

    const sentBody = call.json as Record<string, unknown>
    expect(sentBody.parent).toEqual({ database_id: 'db-123' })
    expect(sentBody.properties).toEqual({
      'Deal Title': {
        title: [{ text: { content: 'Test Deal' } }],
      },
      'Deal Value': { number: 5000 },
      Owner: { rich_text: [{ text: { content: 'John Smith' } }] },
      'Close Date': { date: { start: '2024-07-15' } },
    })
  })

  it('throws descriptive error when title is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { value: 100, owner: 'Owner', close_date: '2024-01-01' } as unknown as PipedriveDealPayload
    const config: ConnectorConfig = { notionApiKey: 'k', notionDatabaseId: 'db', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: title')
  })

  it('throws descriptive error when value is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { title: 'Deal', owner: 'Owner', close_date: '2024-01-01' } as unknown as PipedriveDealPayload
    const config: ConnectorConfig = { notionApiKey: 'k', notionDatabaseId: 'db', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: value')
  })

  it('throws descriptive error when owner is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { title: 'Deal', value: 100, close_date: '2024-01-01' } as unknown as PipedriveDealPayload
    const config: ConnectorConfig = { notionApiKey: 'k', notionDatabaseId: 'db', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: owner')
  })

  it('throws descriptive error when close_date is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { title: 'Deal', value: 100, owner: 'Owner' } as unknown as PipedriveDealPayload
    const config: ConnectorConfig = { notionApiKey: 'k', notionDatabaseId: 'db', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: close_date')
  })

  it('throws with status and endpoint on non-2xx response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401))
    const payload: PipedriveDealPayload = {
      title: 'Deal',
      value: 100,
      owner: 'Owner',
      close_date: '2024-01-01',
    }
    const config: ConnectorConfig = { notionApiKey: 'k', notionDatabaseId: 'db', fetch }

    await expect(handle(payload, config)).rejects.toThrow(
      'Notion API error: 401 Unauthorized for POST https://api.notion.com/v1/pages'
    )
  })

  it('uses injected fetch over global fetch', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.notion.com/v1/pages' ? jsonResponse(TARGET_ENDPOINTS[0].response, 200) : jsonResponse({}, 404)
    )

    const payload: PipedriveDealPayload = {
      title: 'Injected Fetch Test',
      value: 1,
      owner: 'Tester',
      close_date: '2024-01-01',
    }

    const config: ConnectorConfig = {
      notionApiKey: 'key',
      notionDatabaseId: 'db',
      fetch,
    }

    await handle(payload, config)
    expect(calls).toHaveLength(1)
  })
})

